&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;
&lt;p data-path-to-node=&quot;20,1,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Medical, dental, and vision insurance&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;
&lt;p data-path-to-node=&quot;20,2,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Life and disability insurance&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;
&lt;p data-path-to-node=&quot;20,3,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Generous paid time off including vacation, sick leave, floating and fixed holidays&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;
&lt;p data-path-to-node=&quot;20,4,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Maternity and bonding leave&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;
&lt;p data-path-to-node=&quot;20,5,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Employee Assistance Program (EAP) and other wellbeing resources&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
